79|// Strict parse at the trust boundary: exact fields only, so a client
80|// bug cannot silently spend budget on a misread request.
81|export function parseImageRequest(json: unknown): ImageRequest {
82|  if (!isRecord(json)) throw new ImageValidationError();
83|  const { kind } = json;
84|  if (kind === "passage") {
85|    const keys = Object.keys(json).sort().join(",");
86|    if (keys !== "bookId,kind,n,textVersion" && keys !== "bookId,kind,n,style,textVersion") {
87|      throw new ImageValidationError();
88|    }
89|    if (typeof json.bookId !== "string" || json.bookId.length === 0) throw new ImageValidationError();
90|    if (typeof json.textVersion !== "string" || json.textVersion.length === 0) {
91|      throw new ImageValidationError();
92|    }
93|    if (typeof json.n !== "number" || !Number.isInteger(json.n)) throw new ImageValidationError();
94|    const style = parseStyleChoice(json.style);
95|    return {
96|      kind: "passage",
97|      bookId: json.bookId,
98|      textVersion: json.textVersion,
99|      n: json.n,
100|      ...(style === undefined ? {} : { style }),
101|    };
102|  }
103|  if (kind === "scene") {
104|    const keys = Object.keys(json).sort().join(",");
105|    if (keys !== "bookId,kind,sceneId,textVersion" && keys !== "bookId,kind,sceneId,style,textVersion") {
106|      throw new ImageValidationError();
107|    }
108|    if (typeof json.bookId !== "string" || json.bookId.length === 0) throw new ImageValidationError();
109|    if (typeof json.textVersion !== "string" || json.textVersion.length === 0) {
110|      throw new ImageValidationError();
111|    }
112|    if (typeof json.sceneId !== "string" || json.sceneId.length === 0) throw new ImageValidationError();
113|    const style = parseStyleChoice(json.style);
114|    return {
115|      kind: "scene",
116|      bookId: json.bookId,
117|      textVersion: json.textVersion,
118|      sceneId: json.sceneId,
119|      ...(style === undefined ? {} : { style }),
120|    };
121|  }
122|  throw new ImageValidationError();
