132|// Checks the parsed request against the frozen book text.
133|export function validateAgainstBook(req: ImageRequest, book: BookRef): void {
134|  if (req.bookId !== book.id) throw new ImageValidationError();
135|  if (req.textVersion !== book.textVersion) throw new ImageValidationError();
136|  if (req.kind === "passage") {
137|    if (!book.paragraphNs.has(req.n)) throw new ImageValidationError();
138|    return;
139|  }
140|  if (!book.sceneIds.has(req.sceneId)) throw new ImageValidationError();
