143|// One paragraph maps to one image; one scene maps to one image. A styled
144|// image keeps the same base with a style segment before the file name, so
145|// an omitted style keys byte-identically to today.
146|export function imageKey(req: ImageRequest): string {
147|  const base = `images/${req.bookId}/${req.textVersion}/${PROMPT_VERSION}`;
148|  const file = req.kind === "passage" ? `p${req.n}.webp` : `scene-${req.sceneId}.webp`;
149|  return req.style === undefined ? `${base}/${file}` : `${base}/${styleSegment(req.style)}/${file}`;
