1|// Persisted image style for POST /api/images. Modelled on music-prefs:
2|// storage can throw (private mode), so every access is guarded. Shape is
3|// validated, never throws; the server re-checks the text rules.
4|import { IMAGE_STYLE_PRESETS } from "@/core/image-style";
5|import type { ImageStylePresetId, StyleChoice } from "@/core/image-style";
6|
7|export const IMAGE_STYLE_PREFS_KEY = "lectoria.imageStyle.v1";
8|
9|const PRESET_IDS: ReadonlySet<string> = new Set(IMAGE_STYLE_PRESETS.map((p) => p.id));
10|
11|function validChoice(json: unknown): StyleChoice | null {
12|  if (typeof json !== "object" || json === null || Array.isArray(json)) return null;
13|  const keys = Object.keys(json);
14|  if (keys.length !== 1) return null;
15|  const record = json as Record<string, unknown>;
16|  if (keys[0] === "preset") {
17|    return typeof record.preset === "string" && PRESET_IDS.has(record.preset)
18|      ? { preset: record.preset as ImageStylePresetId }
19|      : null;
20|  }
21|  if (keys[0] === "custom") {
22|    return typeof record.custom === "string" && record.custom.length > 0
23|      ? { custom: record.custom }
24|      : null;
25|  }
26|  return null;
27|}
28|
29|export function loadImageStyle(): StyleChoice | null {
30|  try {
31|    if (typeof window === "undefined") return null;
32|    const raw = window.localStorage.getItem(IMAGE_STYLE_PREFS_KEY);
33|    if (!raw) return null;
34|    return validChoice(JSON.parse(raw));
35|  } catch {
36|    return null;
37|  }
38|}
39|
40|export function saveImageStyle(choice: StyleChoice | null): void {
41|  try {
42|    if (typeof window === "undefined") return;
43|    if (choice === null) window.localStorage.removeItem(IMAGE_STYLE_PREFS_KEY);
44|    else window.localStorage.setItem(IMAGE_STYLE_PREFS_KEY, JSON.stringify(choice));
45|  } catch {
46|    // Private mode: new images fall back to the default style.
47|  }
