1|// Drawing style preference: UI only until the /api/images style
2|// contract lands. Persisted in localStorage, parsed defensively.
3|export const IMAGE_STYLE_KEY = "lectoria.imageStyle";
4|
5|export type ImageStylePref = { kind: "preset"; id: string } | { kind: "custom"; text: string };
6|
7|export interface StylePreset {
8|  id: string;
9|  label: string;
10|}
11|
12|export const STYLE_PRESETS: StylePreset[] = [
13|  { id: "denslow", label: "Denslow ink (1900)" },
14|  { id: "watercolour", label: "Watercolour" },
15|  { id: "pencil", label: "Pencil sketch" },
16|  { id: "woodcut", label: "Woodcut" },
17|  { id: "gouache", label: "Storybook gouache" },
18|];
19|
20|export const DEFAULT_IMAGE_STYLE: ImageStylePref = { kind: "preset", id: "denslow" };
21|
22|export const STYLE_OTHER_VALUE = "__other";
23|
24|// The select shows Other… while its custom field is open, even when the
25|// saved pref is still a preset; Escape or a preset choice closes it.
26|export function resolveStyleSelect(pref: ImageStylePref, otherOpen: boolean): string {
27|  return otherOpen || pref.kind === "custom" ? STYLE_OTHER_VALUE : pref.id;
28|}
29|
30|export const DENSLOW_CREDIT = "In the style of W. W. Denslow";
31|
32|export function parseImageStylePref(json: unknown): ImageStylePref {
33|  if (typeof json === "object" && json !== null && !Array.isArray(json)) {
34|    const pref = json as Record<string, unknown>;
35|    if (pref.kind === "preset" && typeof pref.id === "string" && STYLE_PRESETS.some((p) => p.id === pref.id)) {
36|      return { kind: "preset", id: pref.id };
37|    }
38|    if (pref.kind === "custom" && typeof pref.text === "string" && pref.text.trim().length > 0) {
39|      return { kind: "custom", text: pref.text.trim().slice(0, 60) };
40|    }
41|  }
42|  return DEFAULT_IMAGE_STYLE;
43|}
44|
45|export function loadImageStylePref(): ImageStylePref {
46|  try {
47|    if (typeof window === "undefined") return DEFAULT_IMAGE_STYLE;
48|    const raw = window.localStorage.getItem(IMAGE_STYLE_KEY);
49|    if (!raw) return DEFAULT_IMAGE_STYLE;
50|    return parseImageStylePref(JSON.parse(raw));
51|  } catch {
52|    return DEFAULT_IMAGE_STYLE;
53|  }
54|}
