49|async function postImage(body: unknown): Promise<ImageResponse> {
50|  const res = await fetch("/api/images", {
51|    method: "POST",
52|    headers: { "Content-Type": "application/json" },
53|    body: JSON.stringify(body),
54|  });
55|  return (await res.json()) as ImageResponse;
