58|async function poll(body: unknown): Promise<{ url: string; caption: string }> {
59|  let left = POLL_MAX;
60|  for (;;) {
61|    let res: ImageResponse;
62|    try {
63|      res = await postImage(body);
64|    } catch {
65|      throw new Error(MSG_FAILED);
66|    }
67|    if (res.status === "ready") return { url: res.url, caption: res.caption };
68|    if (res.status === "error") throw new Error(res.message);
69|    left -= 1;
70|    if (left <= 0) throw new Error(MSG_RETRY);
71|    await new Promise((done) => setTimeout(done, POLL_MS));
72|  }
