22|function toResponse(res: ImageResponse): { json: ImageResponse; status: number } {
23|  if (res.status === "ready" || res.status === "pending") return { json: res, status: 200 };
24|  const status = res.code === "bad_request" ? 400 : res.code === "quota" ? 429 : 503;
25|  return { json: res, status };
26|}
27|
28|export async function handleImagesPost(req: Request): Promise<Response> {
29|  const capped = await readBodyCapped(req, MAX_IMAGE_BODY_BYTES);
30|  if (!capped.ok) {
31|    return Response.json(
32|      { status: "error", code: "bad_request", message: MSG_BAD_REQUEST } satisfies ImageResponse,
33|      { status: capped.reason === "too_large" ? 413 : 400 },
34|    );
35|  }
36|
37|  let parsed: ImageRequest;
38|  try {
39|    parsed = parseImageRequest(JSON.parse(capped.text));
40|  } catch (e) {
41|    if (e instanceof ImageStyleError) {
42|      return Response.json(
43|        { status: "error", code: "bad_request", message: MSG_STYLE } satisfies ImageResponse,
44|        { status: 400 },
45|      );
46|    }
47|    return Response.json(
48|      { status: "error", code: "bad_request", message: MSG_BAD_REQUEST } satisfies ImageResponse,
49|      { status: 400 },
50|    );
51|  }
52|
53|  let env;
54|  try {
55|    env = readImageEnv();
56|  } catch (e) {
57|    const message = e instanceof Error ? e.message : "";
58|    const prefix = "missing image env:";
59|    const names = message.startsWith(prefix) ? message.slice(prefix.length).trim() : "";
60|    console.warn(`image env missing: ${names}`);
61|    return Response.json(
62|      { status: "error", code: "unavailable", message: MSG_UNAVAILABLE } satisfies ImageResponse,
63|      { status: 503 },
64|    );
65|  }
66|
67|  try {
68|    const { book, scenes } = loadOzBook();
69|    try {
70|      validateAgainstBook(
71|        parsed,
72|        {
73|          id: book.id,
74|          textVersion: book.textVersion,
75|          paragraphNs: new Set(book.paragraphs.map((p) => p.n)),
76|          sceneIds: new Set(scenes.map((s) => s.id)),
77|        },
78|      );
79|    } catch {
80|      return Response.json(
81|        { status: "error", code: "bad_request", message: MSG_BAD_REQUEST } satisfies ImageResponse,
82|        { status: 400 },
83|      );
84|    }
85|
86|    const byN = new Map(book.paragraphs.map((p) => [p.n, p.text]));
87|    const sceneOf = scenes.find((s) =>
88|      parsed.kind === "passage" ? parsed.n >= s.start_n && parsed.n <= s.end_n : s.id === parsed.sceneId,
89|    );
90|    const sceneParas = sceneOf
91|      ? book.paragraphs.filter((p) => p.n >= sceneOf.start_n && p.n <= sceneOf.end_n)
92|      : [];
93|    const content: ImageContent = {
94|      passageText: parsed.kind === "passage" ? (byN.get(parsed.n) ?? "") : "",
95|      sceneTitle: sceneOf?.title ?? "",
96|      sceneClip: sceneParas.map((p) => p.text).join(" "),
